TLM.f("Sancti/07-07",{"officium":"Ss. Cyrilli et Methodii Pont. et Conf.","rule":["Evangelium non appropriatum","Gloria"],"fallback":"Commune/C4","sections":{"Introitus":[{"k":"ref","la":"Ps 131,9-10"},{"k":"text","la":"Sacerdótes tui, Dómine, índuant justítiam, et sancti tui exsúltent: propter David servum tuum, non avértas fáciem Christi tui. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 131:1"},{"k":"text","la":"Meménto, Dómine, David: et omnis mansuetúdinis ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sacerdótes tui, Dómine, índuant justítiam, et sancti tui exsúltent: propter David servum tuum, non avértas fáciem Christi tui. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui Slavóniæ gentes per beátos Confessóris tuos atque Pontífices Cyríllum et Methódium ad agnitiónem tui nóminis veníre tribuísti: præsta; ut, quorum festivitáte (commemoratióne) gloriámur, eórum consórtio copulémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos"},{"k":"ref","la":"Hebr 7:23-27"},{"k":"text","la":"Fratres: Plures facti sunt sacerdótes, idcírco quod morte prohiberéntur permanére: Jesus autem, eo quod máneat in ætérnum, sempitérnum habet sacerdótium. Unde et salváre in perpétuum potest accedéntes per semetípsum ad Deum: semper vivens ad interpellándum pro nobis. Talis enim decébat, ut nobis esset póntifex, sanctus, ínnocens, impollútus, segregátus a peccatóribus, et excélsior cœlis factus: qui non habet necessitátem cotídie, quemádmodum sacerdótes, prius pro suis delíctis hóstias offérre, déinde pro pópuli: hoc enim fecit semel, seípsum offeréndo, Jesus Christus, Dóminus noster."}],"Graduale":[{"k":"ref","la":"Ps 131:16-17"},{"k":"text","la":"Sacerdótes ejus índuam salutári: et sancti ejus exsultatióne exsultábunt."},{"k":"text","la":"Illuc prodúcam cornu David: parávi lucérnam Christo meo. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Jurávit Dóminus, et non poenitébit eum: Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Jurávit Dóminus, et non pœnitébit eum: Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 10:1-9"},{"k":"text","la":"In illo témpore: Designávit Dóminus et álios septuagínta duos: et misit illos binos ante fáciem suam in omnem civitátem et locum, quo erat ipse ventúrus. Et dicebat illis: Messis quidem multa, operárii autem pauci. Rogáte ergo Dóminum messis, ut mittat operários in messem suam. Ite: ecce, ego mitto vos sicut agnos inter lupos. Nolíte portáre sácculum neque peram neque calceaménta; et néminem per viam salutavéritis. In quamcúmque domum intravéritis, primum dícite: Pax huic dómui: et si ibi fúerit fílius pacis, requiéscet super illum pax vestra: sin autem, ad vos revertátur. In eádem autem domo manéte, edéntes et bibéntes quæ apud illos sunt: dignus est enim operárius mercéde sua. Nolíte transíre de domo in domum. Et in quamcúmque civitátem intravéritis, et suscéperint vos, manducáte quæ apponúntur vobis: et curáte infírmos, qui in illa sunt, et dícite illis: Appropinquávit in vos regnum Dei."}],"Offertorium":[{"k":"ref","la":"Ps 67:36"},{"k":"text","la":"Mirábilis Deus in Sanctis suis: Deus Israël, ipse dabit virtútem et fortitúdinem plebi suæ: benedíctus Deus, allelúja."}],"Secreta":[{"k":"text","la":"Preces nostras, quǽsumus, Dómine, et tuórum réspice oblatiónes fidélium: ut tibi gratæ sint in tuórum festivitáte commemoratione Sanctórum, et nobis conferant tuæ propitiatiónis auxílium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 10:27"},{"k":"text","la":"Quod dico vobis in tenebris, dícite in lúmine, dicit Dóminus: et quod in aure audítis, prædicáte super tecta."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, omnípotens Deus: ut, qui nobis múnera dignáris præbére cœléstia, intercedéntibus sanctis tuis Cyríllo et Methódio, despícere terréna concédas."},{"k":"macro","name":"Per Dominum"}]},"hr":{"a9bf8f9449951217":{"t":"Ps 131, 9-10, Ps 131, 1\n(Ps 131, 9-10) Svećenici tvoji, Gospodine, neka obuku pravdu i sveti tvoji neka kliču od radosti. Radi Davida sluge svoga ne prezri lice pomazanika svoga. (Ps 131, 1) Spomeni se, Gospodine, Davida i sve revnosti njegove.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 131, 9-10) Svećenici tvoji, Gospodine, neka obuku pravdu i sveti tvoji neka kliču od radosti. Radi Davida sluge svoga ne prezri lice pomazanika svoga.","kn":"(Ps. 131, 9-10). Svećenici se Tvoji. Gospodine, odjenuli pravdom i radovali se Tvoji sveti: poradi Davida, sluge svoga, ne odbaci pomazanika od sebe. (Ps. 131, 1.) Sjeti se, -Gospodine, Davida i sve njegove pobožnosti. Slava Ocu ... Svecemci se . . .","knRef":"Kniewald 1942, str. 602–603 (snimka 302) (OCR)"},"1707cbe527c3f5a1":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, koji si nas po djelovanju blaženih priznavalaca tvojih i biskupa Ćirila i Metoda priveo k poznavanju svojeg imena, podaj da se pribrojimo društvu onih čiji blagdan slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"∅ → comemoratione","kn":"Svemogući, vječni Bože, koji si dao slavenskim na-rodiiha, da po priznavaocima Tvojim i biskupima Ćirilu i Metodi ju dođu do spoznan ja Imena Tvoga, podaj molimo, da se sjedinimo u društvo onih, kojih blagdan slavimo, po G. n.","knRef":"Kniewald 1942, str. 630–631 (snimka 316) (OCR)"},"3de292c3086c48c6":{"t":"Heb 7, 23-27\nČitanje Poslanice bl. Pavla apostola Hebrejima. Braćo, bilo je mnogo svećenika, jer je došla smrt i nisu mogli ostati. A Isus ima vječno svećeništvo, jer ostaje zauvijek. Zato i može spašavati one koji po njem dolaze k Bogu, jer je trajno naš zagovornik. Trebao nam je upravo takav Veliki svećenik svet, nedužan, neokaljan, odijeljen od grješnika, uzvišeniji od neba. On ne treba kao drugi svećenici svakoga dana prinositi žrtve najprije za svoje grijehe, onda za grijehe naroda, jer je to učinio jedanput, kada je sama sebe prikazao naš Gospodin Isus Krist.","kn":"Čitanje poslanice sv. Pavla apostola Hebrejima (7, 23-27). Braćo! Bilo je mnogo svećenika zato, jer ih je priječila smrt, da ostanu Isus ima vječno >svećeništvo, jer ostaje do vijeka. Zato i može uvijek Spašavati, one, koji po njemu dolaze k Bogu, jer živi uvijek kao naš zagovornik. Dolikovalo je, da imamo takova velikog svećenika, koji je svet, ne- vin, neokaljan, odijeljen od grješnika i uzviSeniji od neba. Njemu ne treba, kao što to čine svećenici, da priniosii svaki dan žrtve najprije za svoje grijehe, zatim za grijehe naroda, jer je to učinio jedamput, kad je samoga sebe prikazao Isus Krist, naš Gospodin.","knRef":"Kniewald 1942, str. 810–811 (snimka 406) (OCR)"},"f6896cd108355439":{"t":"Ps 131, 16-17\nSvećenike ću njegove obući spasenjem i sveti će njegovi klicati u radosti. Ondje ću uzdignuti snagu Davidovu, pripraviti svjetiljku pomazaniku svojem.\n\nPs 109, 4\n<i>Aleluja</i>, <i>aleluja</i>.\nZakleo se Gospodin i neće se pokajati: ti si svećenik dovijeka po redu Melkisedekovu. <i>Aleluja</i>.","kn":"(Ps. 131, 16-17). Svećenike ću sionske odjenuti spasenjem i neka se vesele sdonski sveti! Odanle ću proizvesti Da vidova moćna potomka, pripravit ću svijetlo pomazaniku svome. AIcluja, aleluja.\n\nAleluja, aleluja (Ps, 109, 4). Zakle se Gospodin i ne će se pokajati: Ti si svećenik dovijeka, po redu Melkisedekovu, aleluja.","knRef":"Kniewald 1942, str. 630–631 (snimka 316) (OCR)"},"22b5143a1c0cf786":{"t":"Lk 10, 1-9\nSlijedi sveto Evanđelje po Luki. U ono vrijeme odredi Gospodin i drugu sedamdeset i dvojicu i posla ih dva po dva pred sobom u svaki grad i mjesto kamo je sam kanio doći. I govorio im je: Žetva je velika, a radnika je malo. Zato molite gospodara žetve da pošalje radnike u svoju žetvu. Idite: Evo, ja vas šaljem kao janjce među vukove. Ne nosite ni kese ni torbe ni obuće i nikoga ne pozdravljajte na putu. U kojugod kuću uđete, kažite najprije: Mir ovoj kući! I ako tko ondje bude dostojan mira, ostat će na njemu vaš mir, ako ne bude, vratit će se k vama. Ostanite u onoj kući, jedite i pijte što imaju jer radnik zaslužuje svoju plaću. Ne prelazite iz kuće u kuću. I u kojigod grad uđete i prime vas, jedite, što postave pred vas. I liječite bolesne koji su u njemu, i kažite im: Približilo vam se kraljevstvo Božje!","kn":"t Slijedi sv. evanđelje Po Luki (10, 1-9). U ono vrijeme odredi Gospodin i drugu sedamdeset i dvojicu 1 posla ih dva po dva pred sobom u svaki gnad i mjesto, kamo je sam kanio doći. I govorio, im je: Žetva je velika, a radnika je malo. Zato molite gospodara žetve, da pošalje radnike u svoju žetvu. Idite: Evo, ja vas šaljem kao janjce među vukove. Ne nosite ni kese ni torbe ni obuće, i nikoga ne pozdravljajte na putu. U kojugod kuću uđete, kažite najprije: Mir ovoj kući! I ako tko ondje bude dostojan mira, ostat će na njemu vaš mir, ako ne bude, vratit će se k vama. Ostanite u onoj kući, jedite i pijte, što imaju, jer radnik zaslužuje svoju plaću.. Ne prelazite iz kuće u kuću. I u kojigođ grad uđete 1 prime vas, jedite, što se. donese pred vas. I liječite bolesne, koji su u njemu, i kažite im: Približilo vam se kraljevstvo Božje! .","knRef":"Kniewald 1942, str. 734–735 (snimka 368) (OCR)"},"dd478a333f4e9a0c":{"t":"Ps 67, 36\nDivan je Bog u svojim svetima. Bog Izraelov daje krepost i snagu puku svojemu. Blagoslovljen Bog. <i>Aleluja</i>.","kn":"(Ps. 67, 36). Divan si. Gospodine, u svetištu svojem! Bog Izraelov daje krepost i snagu puku svojemu, blagoslovljen bio Bog!","knRef":"Kniewald 1942, str. 598–599 (snimka 300) (OCR)"},"723dc77774425955":{"t":"Molbe naše i prinos tvojih vjernika, molimo, Gospodine, pogledaj, da ti budu mili o blagdanu tvojih svetaca, a nama da prizovu pomoć tvoga milosrđa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"∅ → comemoratione","kn":"Obazri se, molimo, Gospodine, na moljenje, naše i na prinose svojih vjernika, da Ti budu ugodni na blagdan Tvojih svetih, a nama da pribave: pomoć Tvoga pomilovanja, po G. n.","knRef":"Kniewald 1942, str. 630–631 (snimka 316) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"080d978e8249bb86":{"t":"Mt 10, 27\nŠto vam kažem u tami, razglasujte na svjetlu, kaže Gospodin, i ono što vam na uho šapćem, propovijedajte s krovova. <i>Aleluja</i>.","v":"aleluia → ∅","kn":"(Mt. 10, 27). Što vam govorim u tami, ka'Zujte na svjetlosti, veli Gosjpodin; i što na uho čujete, propovijedajte na krovovima, aleluja.","knRef":"Kniewald 1942, str. 562–563 (snimka 282) (OCR)"},"2f0cd3161c021335":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, da ti, koji si se udostojao dati nam nebeske darove, dadeš po zagovoru svetih svojih Ćirila i Metoda da preziremo zemaljske.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, svemogući Bože, koji se udostojavaš darivati nas nebeskim darovima, podaj, da po zagovoru Tvojih svetih Cirila i Metodija prezremo zemaljske stvari, po G. n.'","knRef":"Kniewald 1942, str. 632–633 (snimka 317) (OCR)"}}});
